-- ----------------------------
-- Table structure for care_knowledge_base
-- ----------------------------
DROP TABLE IF EXISTS `care_knowledge_base`;
CREATE TABLE `care_knowledge_base`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `species` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物种(如：猫、狗、异宠)',
  `breed` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '通用' COMMENT '品种(如：金毛、布偶，默认\"通用\")',
  `life_stage` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '生命阶段(幼年/成年/老年/孕产期)',
  `weight_min` decimal(5, 2) NULL DEFAULT NULL COMMENT '该阶段标准体重下限(kg)',
  `weight_max` decimal(5, 2) NULL DEFAULT NULL COMMENT '该阶段标准体重上限(kg)',
  `kcal_per_kg` int(0) NULL DEFAULT NULL COMMENT '每公斤每日建议热量(kcal)',
  `exercise_mins_per_day` int(0) NULL DEFAULT NULL COMMENT '每日建议基础运动时长(分钟)',
  `diet_advice` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '饮食规范(如：高蛋白、换粮过渡法)',
  `hygiene_advice` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '清洁美容规范(如：长毛需每日梳理，定期挤肛门腺)',
  `medical_advice` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '医疗预防规范(如：关注易发遗传病、按时驱虫)',
  `environment_advice` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '环境心理规范(如：增加独处漏食玩具、猫砂盆数量)',
  `caution` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '绝对禁忌(如：折耳猫禁止补钙、狗禁食葡萄巧克力)',
  `specific_prompt` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '该品种专属的AI提示词(如：你必须以兽医口吻着重强调该品种的心脏病风险)',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_species_breed_stage`(`species`, `breed`, `life_stage`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI 智能养护知识基准表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of care_knowledge_base
-- ----------------------------

-- ----------------------------
-- Table structure for care_plans_day
-- ----------------------------
DROP TABLE IF EXISTS `care_plans_day`;
CREATE TABLE `care_plans_day`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `week_plan_id` bigint(0) NOT NULL COMMENT '关联的周计划ID',
  `pet_id` bigint(0) NOT NULL COMMENT '冗余宠物ID(方便直接查询某宠物的今日任务)',
  `plan_date` date NOT NULL COMMENT '具体执行日期(如: 2026-04-15)',
  `day_of_week` int(0) NOT NULL COMMENT '星期几(1-7，方便前端按星期分类展示)',
  `task_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务分类(饮食、运动、清洁、医疗等)',
  `task_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '具体任务内容',
  `is_completed` tinyint(1) NULL DEFAULT 0 COMMENT '打卡状态(0未完成, 1已完成)',
  `complete_time` datetime(0) NULL DEFAULT NULL COMMENT '实际打卡时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_week_plan`(`week_plan_id`) USING BTREE,
  INDEX `idx_plan_date_pet`(`plan_date`, `pet_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 164 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '每日养护打卡任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of care_plans_day
-- ----------------------------

-- ----------------------------
-- Table structure for care_plans_week
-- ----------------------------
DROP TABLE IF EXISTS `care_plans_week`;
CREATE TABLE `care_plans_week`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(0) NOT NULL COMMENT '用户ID',
  `pet_id` bigint(0) NOT NULL COMMENT '宠物ID',
  `snapshot_age` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '生成时的年龄(如: 3岁2个月)',
  `snapshot_weight` decimal(5, 2) NULL DEFAULT NULL COMMENT '生成时的体重(kg)',
  `snapshot_health_status` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '当时的健康状况(用户填写或OCR提取)',
  `weekly_focus` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'AI生成的本周养护重点',
  `start_date` date NOT NULL COMMENT '本周计划开始日期',
  `end_date` date NOT NULL COMMENT '本周计划结束日期',
  `is_current` tinyint(1) NULL DEFAULT 1 COMMENT '是否为当前生效计划(1生效, 0历史记录)',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '生成时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pet_id`(`pet_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI养护周计划主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of care_plans_week
-- ----------------------------

-- ----------------------------
-- Table structure for comments
-- ----------------------------
DROP TABLE IF EXISTS `comments`;
CREATE TABLE `comments`  (
  `comment_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '评论ID（主键）',
  `post_id` bigint(0) NOT NULL COMMENT '关联的动态ID（外键，关联community_posts的post_id）',
  `user_id` bigint(0) NOT NULL COMMENT '发布评论的用户ID（外键，关联用户表user_id）',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '评论文字内容',
  `parent_id` bigint(0) NULL DEFAULT 0 COMMENT '父评论ID（0表示一级评论，非0表示回复）',
  `like_count` int(0) NULL DEFAULT 0 COMMENT '评论点赞数',
  `report_count` int(0) NULL DEFAULT 0 COMMENT '被举报次数',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '审核状态：0-待审核，1-已发布，2-违规拦截',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '评论发布时间',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '评论更新时间（比如修改内容）',
  `comment_count` int(0) NULL DEFAULT 0 COMMENT '该评论的回复数量',
  PRIMARY KEY (`comment_id`) USING BTREE,
  INDEX `idx_post_id`(`post_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3019 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '社区动态评论表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of comments
-- ----------------------------

-- ----------------------------
-- Table structure for community_posts
-- ----------------------------
DROP TABLE IF EXISTS `community_posts`;
CREATE TABLE `community_posts`  (
  `post_id` bigint(0) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(0) NOT NULL,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '文字内容',
  `media_urls` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '多图地址(JSON序列化)',
  `post_type` tinyint(1) NULL DEFAULT 0 COMMENT '0普通, 1心情分享',
  `like_count` int(0) NULL DEFAULT 0,
  `comment_count` int(0) NULL DEFAULT 0 COMMENT '评论数（冗余字段用于排序）',
  `report_count` int(0) NULL DEFAULT 0 COMMENT '被举报次数',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '审核状态: 0审核中, 1已发布, 2拦截',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `content_vector` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AI语义向量数据',
  PRIMARY KEY (`post_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2037 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of community_posts
-- ----------------------------

-- ----------------------------
-- Table structure for favorites
-- ----------------------------
DROP TABLE IF EXISTS `favorites`;
CREATE TABLE `favorites`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(0) NOT NULL COMMENT '收藏者的用户ID',
  `post_id` bigint(0) NOT NULL COMMENT '被收藏的社区动态ID',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_post`(`user_id`, `post_id`) USING BTREE COMMENT '用户ID和帖子ID的联合唯一索引，防止重复收藏',
  INDEX `idx_user_id`(`user_id`) USING BTREE COMMENT '普通索引，加速查询某用户的收藏列表'
) ENGINE = InnoDB AUTO_INCREMENT = 31009 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户收藏表' ROW_FORMAT = Dynamic;

