-- ----------------------------
-- Table structure for health_records
-- ----------------------------
DROP TABLE IF EXISTS `health_records`;
CREATE TABLE `health_records`  (
  `record_id` bigint(0) NOT NULL AUTO_INCREMENT,
  `pet_id` bigint(0) NOT NULL,
  `checkup_date` date NULL DEFAULT NULL COMMENT '体检日期',
  `report_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '报告图片地址(JSON序列化)',
  `health_score` int(0) NULL DEFAULT 100 COMMENT '健康评分',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '异常备注',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '最后更新时间',
  PRIMARY KEY (`record_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for interaction_notifications
-- ----------------------------
DROP TABLE IF EXISTS `interaction_notifications`;
CREATE TABLE `interaction_notifications`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `receiver_id` bigint(0) NOT NULL COMMENT '接收者(帖子作者)ID',
  `sender_id` bigint(0) NOT NULL COMMENT '发送者(操作人)ID',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '通知类型: LIKE(点赞), COMMENT(评论), FAVORITE(收藏)',
  `post_id` bigint(0) NOT NULL COMMENT '关联的动态/帖子ID',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '附加内容（如评论详情）',
  `is_read` tinyint(1) NULL DEFAULT 0 COMMENT '阅读状态: 0-未读, 1-已读',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '触发时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_receiver_read`(`receiver_id`, `is_read`) USING BTREE COMMENT '加速查询用户的未读消息'
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户互动通知表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of interaction_notifications
-- ----------------------------

-- ----------------------------
-- Table structure for likes
-- ----------------------------
DROP TABLE IF EXISTS `likes`;
CREATE TABLE `likes`  (
  `like_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(0) NOT NULL COMMENT '点赞用户的ID',
  `post_id` bigint(0) NOT NULL COMMENT '被点赞动态的ID',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '点赞时间',
  PRIMARY KEY (`like_id`) USING BTREE,
  UNIQUE INDEX `uk_user_post_like`(`user_id`, `post_id`) USING BTREE COMMENT '联合唯一索引，防止同一用户对同一动态重复点赞',
  INDEX `idx_user_id`(`user_id`) USING BTREE COMMENT '普通索引，加速查询某用户的喜欢列表'
) ENGINE = InnoDB AUTO_INCREMENT = 32020 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户点赞表' ROW_FORMAT = Dynamic;

