-- ----------------------------
-- Table structure for mood_records
-- ----------------------------
DROP TABLE IF EXISTS `mood_records`;
CREATE TABLE `mood_records`  (
  `mood_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '心情记录ID',
  `user_id` bigint(0) NOT NULL COMMENT '所属用户ID(冗余字段，方便直接查询用户的所有日记)',
  `pet_id` bigint(0) NOT NULL COMMENT '宠物ID',
  `record_date` date NOT NULL COMMENT '日记归属日期(如: 2026-04-07)',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '识别原图地址',
  `mood_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '识别出的情绪结果(如: happy, sad)',
  `confidence` double NULL DEFAULT NULL COMMENT 'AI情绪分类置信度',
  `diary_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '大语言模型生成的拟人化宠物日记内容',
  `is_shared` tinyint(1) NULL DEFAULT 0 COMMENT '是否已分享到社区: 0-未分享, 1-已分享',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `is_deleted` tinyint(1) NULL DEFAULT 0 COMMENT '逻辑删除标识: 0-正常, 1-已删除',
  PRIMARY KEY (`mood_id`) USING BTREE,
  INDEX `idx_pet_id`(`pet_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_record_date`(`record_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '宠物心情记录与日记表' ROW_FORMAT = Dynamic;

