-- ----------------------------
-- Table structure for reports
-- ----------------------------
DROP TABLE IF EXISTS `reports`;
CREATE TABLE `reports`  (
  `report_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '举报ID（主键）',
  `reporter_id` bigint(0) NOT NULL COMMENT '举报人用户ID（外键，关联用户表user_id）',
  `target_id` bigint(0) NOT NULL COMMENT '被举报的主体ID（动态ID/评论ID）',
  `target_type` enum('post','comment') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '举报类型：post-动态，comment-评论',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '举报理由（违规、低俗、虚假信息等）',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '处理状态：0-待处理，1-已处理-忽略，2-已处理-删除内容',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '举报时间',
  PRIMARY KEY (`report_id`) USING BTREE,
  INDEX `idx_reporter_id`(`reporter_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_target`(`target_type`, `target_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4007 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户举报记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of reports
-- ----------------------------

