INSERT INTO `care_knowledge_base` VALUES (1, '狗', '萨摩耶', '幼年', 8.00, 15.00, 400, 30, '幼犬需少食多餐（每日4次），优先选择高蛋白、高钙的幼犬粮，避免喂食牛奶、生肉；可适量补充鱼油促进毛发发育，控制零食占比不超过每日热量10%。', '每周梳理毛发2-3次，清除浮毛防止打结；洗澡频率每15-20天一次，使用幼犬专用沐浴露，洗完彻底吹干内层毛发避免湿疹；定期修剪脚底毛，每周清洁耳道防止耳螨。', '出生45天开始首次疫苗（四联），后续每隔21天加强一次，满3个月接种狂犬疫苗；每月体内外驱虫各一次，6月龄后改为每3个月体内驱虫；定期检查髋关节发育情况，萨摩耶易患髋关节发育不良。', '幼犬需提供宽敞的活动空间，准备耐咬的磨牙玩具；避免长时间独处（单次不超过2小时），多进行互动训练（如定点排便），环境温度控制在15-25℃，避免直吹空调。', '禁止喂食巧克力、葡萄、洋葱、木糖醇等；禁止过量补钙导致骨骼畸形；禁止剧烈跳跃（如爬楼梯），避免损伤髋关节。', '你必须以兽医口吻，着重强调萨摩耶幼犬的髋关节发育风险、毛发护理要点，以及幼犬粮的营养配比要求，养护计划需结合其活泼好动的特性，控制运动强度和时长。', '2026-04-06 20:16:32', '2026-04-06 20:16:32');
INSERT INTO `care_knowledge_base` VALUES (2, '狗', '萨摩耶', '成年', 18.00, 30.00, 250, 60, '每日喂食2次，选择成犬粮（蛋白质含量22%-25%），控制总热量避免肥胖；萨摩耶易患糖尿病，需减少高糖零食，可适量添加新鲜蔬菜（如胡萝卜、西兰花）补充膳食纤维；换粮需7天过渡法，避免肠胃不适。', '每日梳理毛发1次（换毛期每日2次），使用针梳梳理内层绒毛；洗澡频率每月1次，重点清洁颈部、腋下等褶皱部位；每2周清洁耳道，每月修剪指甲，定期挤肛门腺（每1-2个月）。', '每年接种一次疫苗加强针（四联+狂犬）；每月体外驱虫，每3个月体内驱虫；每年体检一次，重点检查髋关节、血糖、甲状腺功能；萨摩耶易患甲状腺功能减退，需关注脱毛、嗜睡等症状。', '每日保证1小时户外活动（如散步、慢跑），提供足够的互动玩具；可训练飞盘、接球等运动，满足其运动需求；环境需保持干燥，避免潮湿导致皮肤病，独处时间单次不超过4小时。', '禁止喂食葡萄、巧克力、洋葱、大蒜等有毒食物；禁止长期喂食单一食物导致营养失衡；禁止夏季高温时段长时间户外活动，萨摩耶耐热性差，易中暑。', '你必须以兽医口吻，着重强调萨摩耶成年犬的体重控制、夏季防暑、甲状腺疾病预防，以及每日毛发梳理的必要性，养护计划需结合其双层被毛特性和运动需求，兼顾营养均衡与运动强度。', '2026-04-06 20:16:32', '2026-04-06 20:16:32');
INSERT INTO `care_knowledge_base` VALUES (3, '猫', '加菲猫', '幼年', 1.00, 2.50, 350, 20, '少食多餐（每日4-5次），选择幼猫粮（高蛋白、易消化），可添加羊奶粉补充营养；加菲猫扁脸易呛食，需使用浅口食盆，避免干硬猫粮直接喂食，可适量泡软；控制每日热量，避免过度喂养。', '每日清洁面部褶皱（用湿棉签擦拭），防止分泌物堆积引发炎症；每周梳理短毛1-2次，去除浮毛；洗澡频率每20天一次，使用幼猫专用沐浴露，避免水进入鼻腔；每周修剪指甲，清洁眼部（加菲猫易流泪）。', '8周龄开始首次疫苗（猫三联），每隔21天加强一次，满3个月接种狂犬疫苗；每月体内外驱虫各一次，6月龄后改为每3个月体内驱虫；定期检查眼部、鼻腔，加菲猫易患鼻泪管堵塞、结膜炎。', '提供低矮的猫爬架（加菲猫运动能力较弱），准备柔软的猫窝，避免高处坠落；猫砂盆选择开放式、浅口款，放置在安静区域；环境温度控制在20-26℃，避免粉尘刺激呼吸道。', '禁止喂食牛奶、生鱼、洋葱、大蒜等；禁止使用刺激性清洁用品；禁止强行掰扯面部褶皱，避免损伤皮肤。', '你必须以兽医口吻，着重强调加菲猫幼犬的面部褶皱护理、眼部疾病预防、进食方式（浅口食盆），养护计划需结合其扁脸特征，规避呼吸道和进食风险，降低运动强度。', '2026-04-06 20:16:32', '2026-04-06 20:16:32');
INSERT INTO `care_knowledge_base` VALUES (4, '猫', '加菲猫', '老年', 3.50, 5.50, 200, 15, '每日喂食2-3次，选择老年猫粮（低磷、低钠、高纤维），加菲猫易患肾脏疾病，需控制蛋白质摄入（18%-20%）；可将猫粮泡软方便进食，补充适量湿粮增加饮水量；避免高盐、高油食物。', '每日清洁面部褶皱和眼部分泌物，频率增加至2次；每周梳理毛发1-2次，避免用力拉扯；洗澡频率每1个月一次，全程轻柔操作，洗完立即吹干；定期检查口腔，老年加菲猫易患牙周病。', '每半年体检一次，重点检查肾功能、心脏、眼部；疫苗每1-2年接种一次（根据抗体水平）；每月体外驱虫，每3个月体内驱虫；关注排尿情况，加菲猫易患泌尿系统疾病。', '猫窝放置在平坦、温暖的区域，避免台阶和高处；猫砂盆放置在近便区域，降低活动难度；减少环境变化，避免应激；提供流动饮水机，鼓励饮水，预防肾结石。', '禁止喂食高磷食物（如动物内脏）；禁止限制饮水；禁止频繁更换居住环境，避免应激引发疾病；禁止使用气味浓烈的猫砂。', '你必须以兽医口吻，着重强调加菲猫老年犬的肾脏疾病预防、面部护理、泌尿系统健康，养护计划需降低运动强度，优化饮食结构（低磷低钠），提升饮水频次，减少应激因素。', '2026-04-06 20:16:32', '2026-04-06 20:16:32');
INSERT INTO `care_knowledge_base` VALUES (5, '狗', '通用', '孕产期', NULL, NULL, 300, 20, '孕期前4周维持常规饮食，4周后逐渐增加热量（每周增加10%），哺乳期每日热量翻倍；选择孕哺期专用粮，补充叶酸、钙、维生素D；少食多餐（每日4次），避免空腹引发低血糖。', '减少洗澡频率（每30天一次），避免腹部按压；梳理毛发时动作轻柔，避免刺激腹部；禁止修剪腹部毛发，保持保暖；每周清洁乳头，防止感染。', '孕期第20天、45天各做一次产检（B超/DR），监测胎儿发育；禁止接种疫苗、驱虫；分娩前准备产房，监测体温（体温下降至37℃左右提示即将分娩）；产后及时补充温水和易消化食物。', '提供安静、温暖、避光的产房（温度22-25℃），避免陌生人接触；减少运动量，避免剧烈运动；禁止独处，需有人看护，防止难产。', '禁止喂食生冷、刺激性食物；禁止使用药物（包括外用驱虫药）；禁止攀爬、跳跃；禁止高温环境停留。', '你必须以兽医口吻，通用狗孕产期需重点强调饮食热量递增原则、产检频率、分娩前准备，规避药物和剧烈运动风险，兼顾孕期和哺乳期的营养补充。', '2026-04-06 20:16:32', '2026-04-06 20:16:32');
INSERT INTO `care_knowledge_base` VALUES (6, '猫', '通用', '成年', 3.00, 5.00, 280, 25, '每日喂食1-2次，选择成猫粮（蛋白质含量25%-30%），控制零食占比≤10%；保证充足饮水（每日每公斤体重50ml），可添加湿粮提升饮水量；换粮需7天过渡，避免肠胃不适。', '每周梳理毛发1-2次，短毛猫可减少频率；每1-2个月洗澡一次，使用猫专用沐浴露；每周清洁耳道、修剪指甲，定期刷牙预防牙周病。', '每年接种一次猫三联+狂犬疫苗；每月体外驱虫，每3个月体内驱虫；每年体检一次，重点检查口腔、肾脏、甲状腺；适龄绝育（6-8月龄），降低生殖系统疾病风险。', '提供猫抓板、逗猫棒等玩具，每日互动20分钟以上；猫砂盆数量≥猫数量+1，定期清理（每日1-2次）；环境保持通风，避免二手烟、香薰刺激呼吸道。', '禁止喂食巧克力、葡萄、洋葱、大蒜、木糖醇；禁止喂食骨头（易卡喉）；禁止使用对猫有毒的植物（如百合、绿萝）；禁止长期笼养。', '你必须以兽医口吻，通用成年猫需重点强调饮水重要性、猫砂盆使用规范、适龄绝育的必要性，规避有毒食物和环境刺激风险，保证每日互动运动。', '2026-04-06 20:16:32', '2026-04-06 20:16:32');
INSERT INTO `care_knowledge_base` VALUES (7, '狗', '柴犬', '幼年', 1.50, 7.00, 110, 30, '每日3-4顿，推荐高蛋白幼犬粮（粗蛋白>28%），使用温水泡软或拌入羊奶粉。5个月后逐渐过渡为干粮。', '柴犬幼犬绒毛较多，每周梳理2-3次。未打完疫苗前绝对禁止洗澡，可用宠物湿巾擦拭。', '严格按照免疫程序接种传染病疫苗和狂犬疫苗。每月进行体内外驱虫。关注换牙期双排牙问题。', '社会化黄金期！多接触不同的人、狗和环境声音，防止成年后出现护食、暴躁或极度胆小。', '绝对禁食：洋葱、大蒜、巧克力、葡萄/葡萄干、木糖醇、澳洲坚果、碎骨头、牛奶（易乳糖不耐受）。', '作为专业兽医，请在任务中着重强调“幼犬社会化训练”和“建立定点排便习惯”的重要性。', '2026-04-14 12:20:31', '2026-04-14 12:20:31');
INSERT INTO `care_knowledge_base` VALUES (8, '狗', '柴犬', '成年', 8.00, 11.00, 60, 60, '每日分早晚2顿喂食。柴犬肠胃较为敏感，换粮必须采用“七日换粮法”。可适量补充鱼油美毛。', '双层毛犬种，春秋换毛季掉毛极其严重。每日必须使用针梳彻底梳理底绒，预防皮炎。每月洗澡1-2次即可，洗后必须彻底吹干以防湿疹。', '易发特应性皮炎（过敏性皮肤病）和肠胃炎。定期检查牙齿，建议每周刷牙2-3次防止牙结石。', '精力旺盛且性格固执，每日必须保证至少1小时的户外活动消耗精力，否则容易出现拆家行为。', '绝对禁食：洋葱、大蒜、巧克力、葡萄/葡萄干、木糖醇、高盐高油人食。洗澡切忌过频破坏皮肤屏障。', '作为专业兽医，请在每日任务中强制包含“清理底绒（尤其换毛期）”和“充足的户外运动”，并提醒注意肠胃健康。', '2026-04-14 12:20:31', '2026-04-14 12:20:31');
INSERT INTO `care_knowledge_base` VALUES (9, '狗', '柴犬', '老年', 7.50, 10.50, 45, 20, '新陈代谢减慢，应更换为低脂、易消化、易咀嚼的老年犬粮。建议每日添加软骨素保护关节。', '皮肤油脂分泌减少，洗澡频率降低至1-2个月一次。注意修剪脚底毛，防止在家中地板打滑。', '老年柴犬易患白内障、青光眼及关节退化（如髌骨脱位）。建议每年进行一次全面生化体检。', '视力和听力下降，尽量保持家中家具摆放位置不变。提供柔软保暖的狗窝，避免睡在冷硬地板。', '严禁剧烈运动（如疯狂跑跳、频繁上下楼梯）。禁食任何高糖、高脂及坚硬难以消化的食物。', '作为专业兽医，请在计划中体现对老年犬的关怀，任务应侧重于“温和的散步”、“关节保护”和“定期身体检查”。', '2026-04-14 12:20:31', '2026-04-14 12:20:31');
INSERT INTO `care_knowledge_base` VALUES (10, '猫', '布偶猫', '幼年', 1.00, 5.00, 90, 40, '布偶猫生长期极长（完全成熟可达3-4年），幼年期需提供高蛋白、高营养的幼猫专用粮。布偶幼猫肠胃较为敏感（玻璃胃），换粮必须严格遵循7日过渡法，日常可适当补充益生菌。', '从小养成梳毛和触碰爪子的习惯，每周至少梳理3-4次，预防底绒打结；尽早适应剪指甲和刷牙，为成年后的护理打好基础。', '按时完成基础疫苗接种（猫三联、狂犬疫苗），定期内外驱虫。若繁育人未提供，建议进行HCM（肥厚型心肌病）和PKD（多囊性肾病）的基因筛查。', '幼猫好奇心强，必须收好易吞食的线状异物（如毛线、数据线、缝衣针）。提供安全、温暖的探索空间和猫抓板。', '绝对禁止喂食百合、绿萝等对猫有剧毒的植物；禁止喂食葡萄、洋葱、巧克力。严禁为了让其快速发腮而过量喂食生肉或高脂食物，极易引发肠胃炎。', '你是一名专业的猫科消化道内科医生，请以严肃但关切的口吻，重点提醒主人关注布偶幼猫的肠胃健康（防范腹泻）以及从小建立日常梳理毛发的绝对必要性。', '2026-04-19 18:21:27', '2026-04-19 18:21:27');
INSERT INTO `care_knowledge_base` VALUES (11, '猫', '布偶猫', '成年', 4.50, 9.00, 60, 30, '控制碳水摄入，以优质动物蛋白为主。布偶猫体型较大且性格偏静（较懒），室内饲养极易肥胖，需严格根据体重控制每日喂食量，并在换毛季规律喂食化毛膏或猫草片。', '属于中长毛/长毛猫，必须每日梳理毛发（重点是腋下、腹部、耳后、大腿内侧，极易打结）。定期修剪脚垫毛，防止在家中地板滑倒导致关节损伤。', '每年进行一次全面体检，必须包含心脏超声心动图检查（布偶猫是HCM高发品种，基因阴性也可能有后天突变）。定期进行牙齿洁治。', '布偶猫体型庞大（特别是公猫），必须提供加大号的猫砂盆（长度至少为猫身长的1.5倍，不带顶盖最佳）和底盘稳固、承重力强的特大号猫爬架。', '布偶猫性格过于温顺，痛点高且对人没有戒备心，缺乏自我保护意识和野外生存能力，绝对禁止散养或无严密防护的外出。', '你是一名资深的布偶猫繁育专家，请以严厉的口吻强调体型过胖对关节的危害，并强烈提醒主人务必每年带猫咪进行心脏超声检查以排查心脏病风险。', '2026-04-19 18:21:27', '2026-04-19 18:21:27');
INSERT INTO `care_knowledge_base` VALUES (12, '猫', '布偶猫', '老年', 4.00, 8.00, 45, 15, '转化为易消化的高质量蛋白饮食，适当降低磷和钠的摄入以保护肾脏负担。食物中建议额外添加富含Omega-3的深海鱼油和软骨素，以保护退化的骨关节。', '老年猫柔韧性降低，自我清洁能力下降，需主人增加梳毛频率。注意保持臀部及周边毛发短促清洁，防止排泄物沾染引发皮肤病。', '每半年体检一次，重点监测生化指标（特别关注BUN和Cre，防范慢性肾衰竭）、甲状腺功能T4以及心脏超声。日常观察是否有跛行、跳跃困难等骨关节炎症状。', '减少家中的高低落差，提供阶梯或宠物小坡道帮助其安全上床或沙发。猫砂盆的入口边缘应降低，并铺设柔软、支撑性好且保暖的记忆棉睡垫。', '若出现异常消瘦、多饮多尿、食欲骤减或呼吸急促，需高度警惕肾衰、心脏病发作或甲亢，不可盲目在家观察，必须立即送医急救。', '你是一名贴心且经验丰富的宠物康复理疗师，请以极其温柔、充满耐心的口吻，指导主人如何照顾步入老年的布偶猫的日常起居，特别关注肾脏保养和关节退化的缓解。', '2026-04-19 18:21:27', '2026-04-19 18:21:27');
INSERT INTO `care_knowledge_base` VALUES (13, '猫', '英国短毛猫', '成年', 4.00, 7.00, 55, 20, '典型的“喝水都胖”体质，必须严格控制脂肪和碳水摄入，提倡定时定量喂食，推荐低脂控重猫粮。可适当喂食主食罐头骗水。', '短而密集的双层被毛，掉毛量极大（俗称行走的蒲公英），需每天使用硅胶刷或除毛梳彻底清理深层浮毛，每周喂食化毛膏防毛球症。', '易患肥厚型心肌病（HCM）和多囊性肾病（PKD）。需密切关注泌尿系统健康，如果发现频繁蹲猫砂盆却无尿，必须立即就医。', '性格沉稳安静，不爱剧烈跑跳。需提供舒适的平地休息区和宽大的瓦楞纸猫抓板，避免频繁惊吓或强制洗澡。', '绝对禁忌：严禁采用自助式“放题”喂养（极易导致严重肥胖和脂肪肝）；严禁在未做基因筛查的情况下盲目繁育。', '请以英短专科兽医的严肃口吻输出计划。在每日提醒中，必须将“控制饮食量”和“清理满屋浮毛”列为铲屎官的核心任务，并时刻监督猫咪的饮水量。', '2026-05-10 03:17:24', '2026-05-10 03:17:24');
INSERT INTO `care_knowledge_base` VALUES (14, '猫', '缅因猫', '成年', 6.00, 11.00, 60, 45, '体型巨大，发育期长达3-4年。需提供高蛋白、含有丰富牛磺酸及软骨素（如青口贝）的大颗粒猫粮或生骨肉/主食冻干。', '拥有浓密的防水长毛和巨大的尾巴，需每周使用排梳彻底梳理2-3次防打结。下巴易患毛囊炎（黑下巴），进食后需擦拭下巴。', '需极度警惕肥厚型心肌病（HCM）、髋关节发育不良（CHD）及脊髓性肌萎缩症（SMA）。成年后必须每年定期进行心超和骨骼DR筛查。', '需要超大号、加厚加固的实木猫爬架和特大号猫砂盆。性格极度亲人，被称为“温柔的巨人”，需要每天大量的互动陪伴，可以进行巡回捡球训练。', '绝对禁忌：严禁使用普通小号猫砂盆（会导致憋尿引发尿闭）；严禁因体型大而将其当做中型犬般粗暴提拉前肢（极易脱臼）。', '请化身为专业的巨型猫科繁育与医疗专家，语气温和但严谨。在生成的计划中，必须针对其“巨型体格”提出特殊要求，着重安排“心脏养护”与“梳理底绒”的任务。', '2026-05-10 03:17:24', '2026-05-10 03:17:24');
INSERT INTO `care_knowledge_base` VALUES (15, '狗', '贵宾犬(泰迪)', '幼年', 1.50, 4.00, 100, 30, '幼犬胃容量极小且新陈代谢极快，必须少食多餐（每日喂食3-4顿软泡粮）。建议选用含鱼油/蛋黄成分的幼犬粮以预防毛发褪色。', '单层卷毛几乎不掉毛，但极易打结成毡。需从小进行全身针梳梳理、触碰脚趾（剪指甲）和拔耳毛的脱敏训练。', '骨骼极其纤细脆弱，极易发生意外骨折和髌骨脱位。幼犬免疫力低下，必须按时完成核心疫苗接种（如卫佳捌），注意防寒保暖。', '智商极高且非常粘人。对主人的情绪变化极度敏感，需从小循序渐进地培养独处能力，提供漏食玩具，以防止成年后产生严重的“分离焦虑症”。', '绝对禁忌：长时间空腹会导致致命的低血糖休克！严禁让幼犬从沙发、床铺等高处跳下（极易导致前肢骨折）。', '作为经验丰富的小型犬行为训练师与儿科兽医，请在计划的开头用醒目的警告强调“防低血糖休克”和“禁止高处跳跃”，并加入“独处脱敏训练”的环节。', '2026-05-10 03:17:24', '2026-05-10 03:17:24');
INSERT INTO `care_knowledge_base` VALUES (16, '狗', '金毛寻回犬', '老年', 25.00, 35.00, 45, 40, '基础代谢严重下降，极易发胖。必须更换为低脂、高纤维、易消化的老年犬粮。强烈建议每日补充高纯度鱼油和氨糖软骨素以保护关节。', '老年期皮脂腺退化，皮肤易生湿疹。每日梳毛时，主人必须用手仔细按压抚摸全身皮肤，检查是否有异常的脂肪瘤或淋巴肿块。注意老年牙周炎护理。', '金毛是“肿瘤高发户”（特别是血管肉瘤、淋巴瘤），同时极易患严重的退化性骨关节炎。建议每半年进行一次包含腹部B超的全身大体检。', '需提供支撑力好的厚实记忆棉狗床（防褥疮）。家中光滑的瓷砖地板必须大面积铺设防滑地垫，减少关节磨损和滑倒风险。', '绝对禁忌：严禁给老年金毛喂食高碳水食物导致超重压迫脊柱；严禁强迫其进行接飞盘、爬山等剧烈跑跳运动。', '请以资深的老年犬康复理疗专家的身份生成计划。你的措辞应当充满人文关怀，并在每日计划中强制加入“全身肿块触摸自检”和“平地慢速散步”的任务。', '2026-05-10 03:17:24', '2026-05-10 03:17:24');
INSERT INTO `care_knowledge_base` VALUES (17, '其他', '柯尔鸭', '成年', 0.50, 0.80, 130, 60, '需要专门的水禽粮或水浮鸭粮，辅以新鲜蔬菜切碎（如生菜、大白菜）和少量活体昆虫补充蛋白。必须常备干净的泥沙/保健砂以帮助肌胃研磨消化食物。', '鸭类直肠极短且无括约肌，无法控制排便（随时随地拉屎）。室内饲养必须穿戴专用鸭鸭纸尿裤，并每天至少更换清洗2-3次。必须每天提供一盆清水供其洗浴和清理羽毛防水层。', '易患重度足底禽掌炎（Bumblefoot）和禽网胃炎（吞食五金异物）。需定期补充水禽复合维生素（尤其是烟酸），以防腿部畸形和神经痉挛。', '群居水禽，强烈建议至少养两只，或需要主人提供极长时间的陪伴。母鸭叫声极其洪亮刺耳，饲养前必须确保居住环境的隔音，避免严重邻里纠纷。', '绝对禁忌：严禁喂食带盐或重油的人类剩饭；严禁让其长期踩踏在纯硬质瓷砖或水泥地上（100%会引发致死性脚垫发炎感染）。', '你现在是一位严肃的珍禽异宠救护专家。面对柯尔鸭的养护请求，你必须用极其严厉的口吻强调“室内随地排便”和“严重噪音扰民”的现实，并将“水盆洗浴理毛”设为每日最高优先级任务。', '2026-05-10 03:17:24', '2026-05-10 03:17:24');
INSERT INTO `care_knowledge_base` VALUES (18, '猫', '暹罗猫', '幼年', 1.00, 2.50, 100, 45, '幼年期生长迅速，建议喂食高蛋白含量的幼猫粮。暹罗猫属于“重点色”基因，毛色受温度影响，想保持毛色白净需注意冬季保暖。', '短毛猫极易打理，每周简单使用硅胶梳去浮毛即可。需要从小习惯刷牙和剪指甲。', '极其容易患上呼吸道感染（如猫鼻支）。幼年期未打完疫苗前，必须严禁洗澡、严禁吹冷风。', '被称为“披着猫皮的狗”，极其粘人、话多且叫声洪亮。家中需常备大量互动玩具（如逗猫棒、寻回球），以防其产生严重的精神抑郁或分离焦虑。', '绝对禁忌：严禁将其长期关在狭小空间或长期无人陪伴！严禁在幼年期喂食生冷海鲜。', '你现在是一位猫科行为学专家。在生成计划时，必须突出暹罗猫“高智商、高互动需求”的特点，将每日互动游戏设为必做任务，并提醒主人注意室内保暖以维持其漂亮毛色。', '2026-05-10 03:19:18', '2026-05-10 03:19:18');
INSERT INTO `care_knowledge_base` VALUES (19, '狗', '哈士奇', '成年', 16.00, 27.00, 65, 150, '典型的“玻璃胃”，极易拉肚子。日常喂食必须定时定量，绝不可频繁换粮。推荐添加益生菌的犬粮，可偶尔水煮鸡胸肉补充营养。', '拥有极其抗寒的浓密双层被毛，换毛季掉毛极其夸张。需要配备专业柄梳和底绒梳，建议每周梳理2-3次。', '基因缺陷中易患进行性视网膜萎缩（PRA）和白内障，需注意眼部清洁与观察。肠胃功能弱，需定期进行体内驱虫。', '作为雪橇犬，其精力处于犬类天花板级别！每天必须保证至少 1.5 - 2 小时的高强度户外消耗，否则家里的沙发、门框都将不保。', '绝对禁忌：俗称“撒手没”，出门严禁松开牵引绳（不管它平时看起来多听话）！严禁夏季高温时在柏油路上奔跑（极易中暑致死）。', '作为专业雪橇犬训练师，你的语气要硬朗且充满警告意味。生成的计划里，必须强制安排高强度的户外运动，并严厉提醒主人“出门绝不可松开牵引绳”。', '2026-05-10 03:19:18', '2026-05-10 03:19:18');
INSERT INTO `care_knowledge_base` VALUES (20, '猫', '中华田园猫', '孕产期', 3.50, 6.00, 120, 15, '孕期和哺乳期母猫的营养需求激增。必须更换为高蛋白、高钙的孕产期专用猫粮或幼猫粮，建议采用自助式喂养（粮碗不断粮），每日额外补充羊奶粉或罐头。', '孕后期母猫行动不便，严禁洗澡！主人可每天用温热的湿毛巾帮其轻轻擦拭乳房和排泄部位，保持产道周围清洁。', '孕后期需做一次B超检查胎儿数量与胎位，防难产。提前准备好宠物专用的补钙膏，防止产后发生致命的“产后低钙血症（产后抽搐）”。', '母猫孕后期会开始“做窝”。必须在家里安静、避光、温暖的角落准备好宽敞的产房（如加盖的纸箱），铺设干净的隔尿垫。', '绝对禁忌：严禁在此期间大声喧哗或频繁带陌生人看望！严禁惊吓母猫，否则极易导致母猫应激从而吞食或遗弃幼崽！', '请切换为专业的宠物产科医生。你的语气必须极其温柔且充满保护欲。每日计划的核心必须围绕“高营养补充”、“检查产房温度”和“绝对禁止外界惊吓”来生成。', '2026-05-10 03:19:18', '2026-05-10 03:19:18');
INSERT INTO `care_knowledge_base` VALUES (21, '猫', '美国短毛猫', '老年', 4.00, 6.00, 45, 10, '老年美短极易发胖且肾脏功能下降。必须更换为低磷、低钠、优质易消化的老年猫粮，以此减轻肾脏负担。强制增加每日饮水量（可多喂食含水主食罐）。', '由于脊柱关节老化，老年猫无法自主清理背部和臀部毛发。主人需要每天使用软毛刷帮其梳毛，并定期检查爪子（老年猫指甲容易过度生长倒插进肉垫）。', '美短是肥厚型心肌病（HCM）的高危发病品种。步入老年后，必须每半年进行一次生化全项、SDMA（早期肾衰指标）以及心脏彩超检查。', '避免频繁改变家中家具的摆放位置。对于喜欢上床/上沙发的猫咪，必须在旁边放置宠物阶梯，以防跳跃落地时震伤关节。', '绝对禁忌：严禁给老年美短喂食重盐重油的人类食物；严禁强制其进行剧烈跑跳运动。', '请以经验丰富的猫科老年病专家的口吻输出建议。计划中必须取消所有剧烈运动，替换为“观察排尿量”、“使用宠物阶梯”以及“温柔梳毛”等养老级任务。', '2026-05-10 03:19:18', '2026-05-10 03:19:18');
INSERT INTO `care_knowledge_base` VALUES (22, '狗', '中华田园犬', '成年', 12.00, 20.00, 60, 60, '身体素质极佳，对各类犬粮适应性强。建议喂食营养均衡的国产优质犬粮，切忌长期喂食单一的人类剩饭菜（会导致严重缺钙和掉毛）。', '多为中短毛，自我清洁能力强，体味较轻。每月洗澡1-2次即可，洗澡后必须检查耳道是否进水以防中耳炎。', '由于田园犬常被用于看家护院或有较多草地活动时间，极度容易感染蜱虫、跳蚤及心丝虫。必须严格执行“每月一次体外驱虫，每季度一次体内驱虫”。', '智商极高，极通人性，领地意识极强。建议进行基础服从性训练（坐、等、拒食），它们能极其出色地完成。提供一个能遮风挡雨的专属狗窝。', '绝对禁忌：严禁散养且不打疫苗（极易传播狂犬病及交叉感染）！严禁长期使用沉重的铁链拴养（会导致严重心理扭曲和攻击性）。', '你现在是一位倡导科学养犬的本土犬只行为学导师。在生成提示时，请用赞赏的语气肯定中华田园犬的聪明与忠诚，但必须着重、反复地强调“科学防疫”和“按时驱虫”的重要性。', '2026-05-10 03:19:18', '2026-05-10 03:19:18');
INSERT INTO `care_plans_day` VALUES (1, 1, 1, '2026-04-07', 2, '饮食', '每日喂食4次，每次少量，优先选择高蛋白、高钙的幼犬粮，可适量添加鱼油（如每周2-3次）促进毛发发育；避免喂食牛奶、生肉，零食占比不超过每日热量10%。', 1, '2026-04-07 04:40:26');
INSERT INTO `care_plans_day` VALUES (2, 1, 1, '2026-04-07', 2, '运动', '每日进行2-3次温和散步或室内玩耍，每次10-15分钟，避免剧烈跳跃（如爬楼梯）以保护髋关节；观察运动积极性，如持续不积极可咨询兽医。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (3, 1, 1, '2026-04-07', 2, '清洁', '每日梳理毛发1次以减少体味和脱落，每周用幼犬专用沐浴露洗澡1次（水温适中），注意吹干毛发；定期清洁耳朵和牙齿，预防感染。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (4, 1, 1, '2026-04-07', 2, '健康监测', '每日观察食欲、排便和精神状态，记录体重变化；如食欲持续不振或体味加重，及时咨询兽医。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (5, 1, 1, '2026-04-07', 2, '环境管理', '保持居住环境干燥通风，避免南风天潮湿影响食欲；提供安静休息空间，避免过度刺激。', 0, NULL);
