INSERT INTO `care_plans_day` VALUES (34, 1, 1, '2026-04-13', 1, '健康监测', '每日观察食欲、排便和精神状态，记录体重变化；如食欲持续不振或体味加重，及时咨询兽医。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (35, 1, 1, '2026-04-13', 1, '环境管理', '保持居住环境干燥通风，避免南风天潮湿影响食欲；提供安静休息空间，避免过度刺激。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (36, 2, 2, '2026-04-07', 2, '饮食', '提供幼猫粮（高蛋白、易消化），每日分4-5次喂食，每次少量；使用浅口食盆，避免呛食；可添加羊奶粉补充营养，禁止喂食牛奶、生鱼、洋葱、大蒜等。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (37, 2, 2, '2026-04-07', 2, '清洁', '轻柔清洁面部褶皱，避免强行掰扯，使用温和清洁用品；观察便便状况，如有持续稀便需记录。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (38, 2, 2, '2026-04-07', 2, '运动', '鼓励轻度活动，如玩猫抓板，但避免强迫；观察蹭门行为，确保环境安全。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (39, 2, 2, '2026-04-08', 3, '饮食', '继续少食多餐，选择幼猫粮，可适量泡软猫粮以利消化；控制每日热量，避免过度喂养。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (40, 2, 2, '2026-04-08', 3, '清洁', '保持食盆和水盆清洁，使用无刺激性清洁剂；检查皮肤是否有异常，避免损伤。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (41, 2, 2, '2026-04-08', 3, '运动', '提供安静环境，允许猫猫自由活动，监测活动水平和蹭门频率。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (42, 2, 2, '2026-04-09', 4, '饮食', '维持少食多餐模式，观察食欲是否改善；如有需要，咨询兽医调整饮食方案。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (43, 2, 2, '2026-04-09', 4, '清洁', '轻柔梳理毛发，减少应激；继续监测便便稠度，记录变化。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (44, 2, 2, '2026-04-09', 4, '运动', '尝试互动游戏以刺激兴趣，但尊重猫猫意愿，避免过度运动。', 0, NULL);
