INSERT INTO `care_plans_day` VALUES (124, 8, 1, '2026-05-10', 7, '运动', '进行短时间的温和互动，如室内牵引散步5分钟，避免剧烈跑跳。根据状态适当增加活动时间。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (125, 9, 1, '2026-05-10', 7, '饮食', '每日4次幼犬粮（高蛋白高钙），每餐约70g，用温水泡软后喂食；加入1ml鱼油混入早餐中。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (126, 9, 1, '2026-05-10', 7, '运动', '进行5分钟短距离慢走，在草地或软地面上进行，用玩具引导；避免剧烈奔跑和跳跃。', 1, '2026-05-10 10:58:47');
INSERT INTO `care_plans_day` VALUES (127, 9, 1, '2026-05-10', 7, '清洁', '梳理毛发5分钟，重点清理耳后和尾部；检查皮肤有无异常。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (128, 9, 1, '2026-05-10', 7, '行为', '进行5分钟简单服从训练（如坐、趴），用零食奖励；每天固定时间互动，增强安全感。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (129, 10, 2, '2026-05-25', 1, '饮食', '每日分4-5次少食多餐，选用幼猫粮（高蛋白易消化），加温水泡软后使用浅口食盆喂食，避免呛食。可搭配羊奶粉补充营养，但需控制热量。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (130, 10, 2, '2026-05-25', 1, '清洁', '每日用宠物专用湿巾（无刺激性）轻轻擦拭泪痕区2次，清理眼角分泌物后涂少量宠物用泪痕粉保持干燥。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (131, 10, 2, '2026-05-25', 1, '运动', '用逗猫棒或激光笔引导猫咪进行5-10分钟互动游戏，分早晚两次进行，避免剧烈运动引发伸舌头。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (132, 10, 2, '2026-05-26', 2, '饮食', '继续分4-5次喂食，确保每餐间隔3-4小时。观察进食情况，若出现伸舌头伴随焦躁，暂停喂食并检查是否呛到。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (133, 10, 2, '2026-05-26', 2, '清洁', '检查面部褶皱是否有红肿或潮湿，用医用棉球沾温水轻轻擦拭褶皱缝隙，再涂薄层宠物用护臀霜隔离。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (134, 10, 2, '2026-05-26', 2, '运动', '放置猫爬架或隧道，鼓励自主攀爬玩耍。若不愿活动，用零食引导短距离慢走。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (135, 10, 2, '2026-05-27', 3, '饮食', '在幼猫粮中加入半勺羊奶粉（按说明比例冲调），观察大便是否成形。避免喂食任何人类食物。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (136, 10, 2, '2026-05-27', 3, '清洁', '每日两次泪痕清洁，若泪痕严重可增加至3次。清洁后滴入宠物用泪痕滴眼液预防感染。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (137, 10, 2, '2026-05-27', 3, '运动', '尝试用羽毛棒逗引猫咪跳跃，每次5分钟。如出现喘息伸舌，立即停止休息并喂水。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (138, 10, 2, '2026-05-28', 4, '饮食', '猫粮继续泡软，并用手捏成小丸方便吞食。控制每顿总量约10-15克，避免过量。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (139, 10, 2, '2026-05-28', 4, '清洁', '更换清洁用品为温和无香型，清洁后用手轻轻扇干泪痕区域，避免毛发潮湿。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (140, 10, 2, '2026-05-28', 4, '运动', '将食物碗放在较高位置，迫使猫咪站立进食以增加活动量。注意食盆稳固防滑。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (141, 10, 2, '2026-05-29', 5, '饮食', '尝试在猫粮中混入少量水煮鸡胸肉丝（无盐），观察食欲变化。如仍不主动吃，用针管喂少量羊奶补充。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (142, 10, 2, '2026-05-29', 5, '清洁', '用宠物专用泪痕湿巾擦拭后，涂极薄一层凡士林保护皮肤，防止泪痕导致嘴角皮炎。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (143, 10, 2, '2026-05-29', 5, '运动', '使用滚动小球玩具，引导猫咪追逐5分钟。若持续伸舌头，可缩短为2分钟一次，每天多次。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (144, 10, 2, '2026-05-30', 6, '饮食', '调整每日总热量不超过250千卡（根据体重计算），避免零食。4-5次喂食中穿插一次纯羊奶。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (145, 10, 2, '2026-05-30', 6, '清洁', '检查眼角是否有异常分泌物，如有黄色脓性分泌物，及时就医。正常泪痕为红褐色氧化色。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (146, 10, 2, '2026-05-30', 6, '运动', '在安静时段用激光笔引导猫咪在地面慢走，每次3分钟。完成后给予少量奖励。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (147, 10, 2, '2026-05-31', 7, '饮食', '总结本周饮食情况：保持少食多餐，幼猫粮+羊奶粉组合可行。若体重无增加，考虑增加蛋白量。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (148, 10, 2, '2026-05-31', 7, '清洁', '每日泪痕清洁如常，确认面部褶皱无破损。备好宠物专用泪痕清洗液，避免用人类产品。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (149, 10, 2, '2026-05-31', 7, '运动', '评估运动耐受力，若仍伸舌头，下一次就诊时咨询心脏健康。本周继续每日5分钟温和互动。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (150, 11, 1, '2026-05-25', 1, '饮食', '每日4次喂食高蛋白、高钙幼犬粮，每顿约50g，间隔4-5小时；添加1ml鱼油到狗粮中，促进毛发发育。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (151, 11, 1, '2026-05-25', 1, '清洁', '使用软梳梳理全身毛发15分钟，重点处理打结处，促进血液循环。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (152, 11, 1, '2026-05-26', 2, '饮食', '继续每日4次喂食，观察进食情况；若食欲不振，尝试用少量温水泡软狗粮增加适口性。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (153, 11, 1, '2026-05-26', 2, '运动', '室内散步10分钟，避免跳跃；与狗狗进行简单互动如握手，消耗精力。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (154, 11, 1, '2026-05-27', 3, '饮食', '在狗粮中添加1ml鱼油；确保全天饮水充足，更换新鲜凉白开。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (155, 11, 1, '2026-05-27', 3, '清洁', '用湿布擦拭眼睛和嘴角周围，保持干净；再次梳理毛发15分钟。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (156, 11, 1, '2026-05-28', 4, '饮食', '尝试加入少量水煮鸡胸肉（约20g）拌入狗粮，提高食欲；继续少量多餐。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (157, 11, 1, '2026-05-28', 4, '运动', '室内散步10分钟，进行嗅觉游戏：用毛巾包裹零食让狗狗寻找。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (158, 11, 1, '2026-05-29', 5, '饮食', '恢复幼犬粮为主食，鱼油改为隔天添加1ml；控制零食量不超过每日热量10%。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (159, 11, 1, '2026-05-29', 5, '清洁', '检查皮肤有无异常，用宠物湿巾清洁爪子；梳毛15分钟。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (160, 11, 1, '2026-05-30', 6, '饮食', '每日4次喂食，观察排便情况（是否成形、颜色正常）；鱼油添加1ml。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (161, 11, 1, '2026-05-30', 6, '运动', '室内散步10分钟，教导基本口令如“坐下”、“过来”。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (162, 11, 1, '2026-05-31', 7, '饮食', '总结本周食欲：若食欲仍不佳，考虑就医检查；继续少食多餐，添加鱼油。', 0, NULL);
INSERT INTO `care_plans_day` VALUES (163, 11, 1, '2026-05-31', 7, '清洁', '洗澡（仅用宠物专用香波），彻底吹干防止感冒；梳理毛发。', 0, NULL);
INSERT INTO `care_plans_week` VALUES (1, 10005, 1, '0', 10.00, '狗狗最近食欲不太好，可能是南风天，运动也不太积极，体味有点重', '针对萨摩耶幼犬（0岁，12.0kg）食欲不振、运动不积极和体味重的问题，本周养护核心是调整饮食结构以刺激食欲、加强温和运动促进新陈代谢，并注重日常清洁以减轻体味。结合幼犬生理特点，需严格遵循少食多餐原则，避免禁忌食物和活动，确保骨骼和关节健康。', '2026-04-07', '2026-04-13', 0, '2026-04-07 03:44:26');
INSERT INTO `care_plans_week` VALUES (2, 10005, 2, '0', 10.00, '猫猫这几日便便很稀，吃东西也很少，平时喜欢玩猫抓板，这几日都不爱玩了，而且总是喜欢用身体去蹭门或是别的什么东西', '针对加菲猫幼猫（0岁，7.0kg）出现稀便、食欲不振和活动减少的症状，本周养护核心建议是：调整饮食结构，采用少食多餐、易消化食物，并密切观察健康状况，避免刺激和过度喂养。', '2026-04-07', '2026-04-12', 0, '2026-04-07 05:07:30');
INSERT INTO `care_plans_week` VALUES (3, 10005, 2, '0', 10.00, '近期天气很热，猫猫食欲不好，睡觉也睡不久，也不爱动', '本周养护核心建议：针对近期天气炎热导致的食欲不振、睡眠不佳和活动减少问题，重点实施少食多餐（每日4-5次），提供幼猫粮（高蛋白、易消化）并适量泡软，使用浅口食盆防止呛食，添加羊奶粉补充营养。同时，注意保持环境凉爽，避免刺激性清洁，并温和处理面部褶皱。', '2026-04-13', '2026-04-19', 0, '2026-04-13 20:45:56');
INSERT INTO `care_plans_week` VALUES (4, 10005, 1, '0', 10.00, '近期胃口很好👌🏻', '本周养护核心建议：针对幼犬萨摩耶，重点实施少食多餐（每日4次），选择高蛋白、高钙的幼犬粮，避免禁忌食物；适量补充鱼油促进毛发发育，控制零食占比；避免剧烈运动以保护髋关节，确保日常清洁和温和运动。', '2026-04-14', '2026-04-19', 0, '2026-04-14 12:09:21');
INSERT INTO `care_plans_week` VALUES (5, 10006, 3, '2', 20.00, '宠物现阶段不爱喝水食欲不振，毛发干燥', '本周养护核心建议：针对柴犬食欲不振和毛发干燥问题，重点通过调整饮食和增加水分摄入来改善健康。建议每日提供3-4顿高蛋白幼犬粮（粗蛋白>28%），使用温水泡软或拌入羊奶粉以增加食欲和水分，同时避免禁忌食物。结合适量运动和日常清洁，以促进新陈代谢和毛发健康。', '2026-04-14', '2026-04-19', 0, '2026-04-14 12:32:14');
INSERT INTO `care_plans_week` VALUES (6, 10006, 4, '0', 8.00, '饮食方面最近胃口也还行，就是不爱活动，掉毛也会有点严重', '针对布偶幼猫（0岁，8.0kg）的周养护计划，核心在于促进活动以改善不爱动的问题，同时管理掉毛和维持健康饮食。重点包括：提供高蛋白幼猫粮、鼓励日常玩耍运动、定期梳理毛发以减少掉毛，并严格遵循饮食禁忌。', '2026-04-19', '2026-04-19', 1, '2026-04-19 18:23:19');
INSERT INTO `care_plans_week` VALUES (7, 10006, 3, '2', 20.00, '近期爱睡觉，懒洋洋的，吃饭也不爱吃', '针对嗜睡、食欲不振，建议增加运动量，改善饮食适口性，观察精神状态，必要时就医排查潜在健康问题。', '2026-04-24', '2026-04-26', 1, '2026-04-24 15:41:33');
INSERT INTO `care_plans_week` VALUES (8, 10005, 1, '0', 10.00, '最近有颜色比较深的便便，不爱活动', '关注排便颜色与活动量，调整饮食结构，观察消化状况。', '2026-05-10', '2026-05-10', 0, '2026-05-10 09:41:57');
INSERT INTO `care_plans_week` VALUES (9, 10005, 1, '0', 10.00, '不开心、不爱运动', '本周重点是缓解狗狗的抑郁情绪，培养运动习惯，并确保科学饮食以支持其生长发育。', '2026-05-10', '2026-05-10', 0, '2026-05-10 10:58:24');
INSERT INTO `care_plans_week` VALUES (10, 10005, 2, '0', 10.00, '泪痕严重，不爱运动，老是伸舌头', '控制泪痕与调整饮食，增加温和互动促进运动', '2026-05-25', '2026-05-31', 1, '2026-05-25 10:27:49');
INSERT INTO `care_plans_week` VALUES (11, 10005, 1, '0', 10.00, '毛发杂乱、食欲不振', '调整饮食结构，增加营养补充；梳理毛发，观察食欲变化', '2026-05-25', '2026-05-31', 1, '2026-05-25 10:48:06');
