INSERT INTO `community_posts` VALUES (2011, 10004, '推荐一款性价比极高的无谷猫粮！我家猫咪吃了几个月，毛发变得很亮，而且便便也不怎么臭了，肠胃敏感的猫咪可以试试。', '[]', 0, 95, 20, 0, 1, '2026-04-12 09:30:00', NULL);
