INSERT INTO `community_posts` VALUES (2024, 10005, '今天带我家柴犬椰椰去公园玩飞盘，它的精力真的太旺盛了，跑了一个下午都不累！大家有没有推荐的消耗狗狗精力的好物呀？', '[]', 0, 12, 3, 0, 1, '2026-05-08 09:00:00', NULL);
INSERT INTO `community_posts` VALUES (2025, 10002, '养柴犬的家人们，你们家狗子换毛期怎么处理的？满屋子都是狗毛，简直像下雪一样，求推荐好用的吸尘器或者宠物专属除毛梳！', '[]', 0, 8, 5, 0, 1, '2026-05-08 10:30:00', NULL);
INSERT INTO `community_posts` VALUES (2026, 10006, '周末适合带狗子去哪里自驾游？最好是那种有大片草坪可以撒欢跑的宠物友好型营地，求坐标分享~', '[]', 1, 5, 1, 0, 1, '2026-05-08 11:15:00', NULL);
INSERT INTO `community_posts` VALUES (2027, 10001, '我家橘猫最近总是不爱喝水，买了好几个不同的自动饮水机都不管用。今天尝试在水里加了一点点冻干碎，总算愿意吧唧吧唧喝两口了，猫主子太难伺候啦。', '[]', 0, 20, 8, 0, 1, '2026-05-09 08:20:00', NULL);
INSERT INTO `community_posts` VALUES (2028, 10004, '猫咪如果出现频繁吐毛球的情况，一定要定期喂化毛膏或者种一点猫草。我通常会每周给家里的两只猫种新鲜的燕麦草，促进肠胃蠕动效果很好。', '[]', 0, 35, 12, 0, 1, '2026-05-09 09:45:00', NULL);
INSERT INTO `community_posts` VALUES (2029, 10001, '求测评！市面上哪款无谷猫粮的适口性比较好？主子最近挑食严重，连以前最爱吃的巅峰都不碰了。', '[]', 0, 6, 2, 0, 1, '2026-05-09 14:10:00', NULL);
INSERT INTO `community_posts` VALUES (2030, 10006, '宠物生病真的太让人揪心了。上周狗狗肠胃炎上吐下泻，连夜送去宠物医院打点滴。提醒各位铲屎官，换粮一定要遵循七日换粮法，千万别突然换！', '[]', 0, 45, 15, 0, 1, '2026-05-10 10:00:00', NULL);
INSERT INTO `community_posts` VALUES (2031, 10004, '新手养宠必看防坑指南：幼犬幼猫时期的核心疫苗和按时体内外驱虫千万不能省。一旦感染细小或者猫瘟，治疗费用高不说，致死率还非常可怕。', '[]', 0, 58, 22, 0, 1, '2026-05-10 11:30:00', NULL);
INSERT INTO `community_posts` VALUES (2032, 10005, '我家萨摩耶快一岁了，出门还是爆冲，拽都拽不住，P链和防爆冲胸背带都试过了效果不大。各位大神有没有什么响片训练或者随行脱敏的好方法？', '[]', 0, 18, 5, 0, 1, '2026-05-11 09:00:00', NULL);
INSERT INTO `community_posts` VALUES (2033, 10002, '最近在教狗子定点大小便，发现零食奖励的时机真的太重要了。晚一秒钟它就不知道你为什么奖励它，建议大家训练前先建立好“Yes”这种明确口令的条件反射。', '[]', 0, 24, 7, 0, 1, '2026-05-11 10:30:00', NULL);
INSERT INTO `community_posts` VALUES (2034, 10006, '关于幼犬护食的问题，千万不要用打骂的方式去强行抢它的饭碗，这样只会让它对你更警惕。应该尝试用更高级的零食去跟它“交换”，慢慢建立信任感。', '[]', 0, 42, 11, 0, 1, '2026-05-11 14:15:00', NULL);
INSERT INTO `community_posts` VALUES (2035, 10001, '小猫半夜总是酷酷跑酷，还喜欢躲在床底咬人脚趾头怎么办？白天已经拿逗猫棒消耗它很久了，晚上还是精力充沛，简直是个小恶魔，求铲屎官们支招！', '[]', 1, 15, 6, 0, 1, '2026-05-12 08:20:00', NULL);
INSERT INTO `community_posts` VALUES (2036, 10004, '很多人问怎么让猫咪乖乖剪指甲。核心就是“系统脱敏”！先从日常触摸爪子开始，没反抗就给冻干奖励；然后试着轻轻按压肉垫，循序渐进，千万不能来硬的。', '[]', 0, 66, 18, 0, 1, '2026-05-12 11:45:00', NULL);
