INSERT INTO `mood_records` VALUES (1, 1, 1, '2026-04-07', 'https://mp-aa1e3790-0b44-4bfc-afa7-9b9be364f376.cdn.bspapp.com/cloudstorage/5de5ce92-63b0-4b28-af65-71d7c57358e2.jpg', 'angry', 0.2582, '本宝宝椰椰今天有点生气呢！(｀へ´*) 昨天主人什么都没安排，害得我无聊了一整天，哼！作为一只可爱的萨摩耶，我需要更多玩耍和关注啦！今天要好好补偿我哦～(｡•́︿•̀｡)', 0, '2026-04-07 16:44:29', NULL, 0);
INSERT INTO `mood_records` VALUES (2, 1, 3, '2026-04-14', 'https://mp-aa1e3790-0b44-4bfc-afa7-9b9be364f376.cdn.bspapp.com/cloudstorage/f07527a2-dd58-4ed9-9dae-ca44180955f0.jpg', 'angry', 0.2535, '本宝宝今天有点生气呢！(｀へ´*) 昨天主人居然没有安排什么特别的计划，害得我无聊了一整天！哼，今天要好好补偿我哦，不然我就继续傲娇给你看！(￣^￣)ゞ', 0, '2026-04-14 12:38:40', NULL, 0);
INSERT INTO `mood_records` VALUES (3, 1, 3, '2026-04-14', 'https://mp-aa1e3790-0b44-4bfc-afa7-9b9be364f376.cdn.bspapp.com/cloudstorage/b331efe5-e414-4ea2-b138-fc1ea6765a27.jpg', 'angry', 0.2535, '本宝宝今天心情angry！(╯°□°）╯︵ ┻━┻ 昨天主人什么都没安排，害得我无聊了一整天，哼！今天必须好好补偿我，不然我就继续傲娇给你看！', 0, '2026-04-14 12:43:22', NULL, 0);
INSERT INTO `mood_records` VALUES (4, 1, 3, '2026-04-18', 'https://mp-aa1e3790-0b44-4bfc-afa7-9b9be364f376.cdn.bspapp.com/cloudstorage/529154a5-3dc1-490d-9188-566098694527.jpg', 'angry', 0.2544, '本宝宝柴柴今天有点生气呢！(｀へ´*) 主人昨天答应的事情都没做完，粮粮没泡软，毛毛没梳理，运动也没陪我玩！哼，本宝宝不开心，要主人今天好好补偿我，不然就汪汪抗议！(｀ω´*)', 0, '2026-04-18 16:31:14', NULL, 0);
INSERT INTO `mood_records` VALUES (5, 1, 2, '2026-05-10', 'https://mp-aa1e3790-0b44-4bfc-afa7-9b9be364f376.cdn.bspapp.com/cloudstorage/5a0dabfa-ac86-40e4-a501-f33b9d1c9c34.jpg', 'happy', 0.2545, '今天本宝宝心情超好！(≧▽≦) 虽然主人昨天没特别安排，但没关系啦，谁让我是可爱的小加菲呢～主人摸摸我的头，我就原谅你啦！(ฅ´ω`ฅ)', 0, '2026-05-10 09:51:59', NULL, 0);
INSERT INTO `mood_records` VALUES (6, 1, 1, '2026-05-10', 'https://mp-aa1e3790-0b44-4bfc-afa7-9b9be364f376.cdn.bspapp.com/cloudstorage/062dc189-f0cf-498f-a272-8ae44e0dc980.jpg', 'happy', 0.2545, '今天超开心！(๑˃̵ᴗ˂̵)و 虽然主人昨天没带我出去玩，但本宝宝原谅你啦！今天一定要好好亲亲你，疯狂摇尾巴～ (≧▽≦) 主人最好了！', 0, '2026-05-10 11:00:03', NULL, 0);
INSERT INTO `mood_records` VALUES (7, 1, 2, '2026-05-25', 'https://mp-aa1e3790-0b44-4bfc-afa7-9b9be364f376.cdn.bspapp.com/cloudstorage/5fee4ebf-3cb2-4b42-b53e-38b4ba3b8246.jpg', 'angry', 0.2554, '本宝宝今天超级不开心！(｀へ´) 昨天主人居然什么都没做，连小鱼干都没给我加！哼，我现在看到罐头都懒得吃，只想趴窝生闷气。希望主人今晚好好补偿我，不然明天继续生气！(｀⌒´メ)', 0, '2026-05-25 10:28:18', NULL, 0);
INSERT INTO `notifications` VALUES (1, 0, '⚠️ 系统升级维护通知', '尊敬的各位宠友：为了提供更稳定的服务，本社区将于本周五凌晨 02:00 - 04:00 进行停机维护，期间将无法发帖和评论，给您带来的不便敬请谅解。', 0, '2026-03-25 11:30:02', 1);
INSERT INTO `notifications` VALUES (2, 0, '📢 社区发言规范更新', '我们更新了《社区友好交流公约》，严禁发布任何虐宠、引流广告及辱骂信息。共建良好养宠环境，从你我做起！', 0, '2026-03-23 11:30:02', 1);
INSERT INTO `notifications` VALUES (3, 1001, '🎉 欢迎来到宠物健康社区', '亲爱的新用户，欢迎您的加入！在这里您可以记录爱宠的健康数据，分享养宠日常，快去发布您的第一条动态吧！', 1, '2026-03-21 11:30:02', 1);
INSERT INTO `notifications` VALUES (4, 1003, '🚫 违规内容处理警告', '您好，系统检测到您最近发布的一条评论涉及违规广告引流，该评论已被管理员屏蔽处理。若多次违规，您的账号将被封禁，请规范您的发言。', 0, '2026-03-26 09:30:02', 1);
INSERT INTO `notifications` VALUES (5, 10005, '🎁 热门动态恭喜', '恭喜！您发布的《狗狗绝育后的护理经验》被评为本周优质精华动态，感谢您为社区做出的贡献！', 0, '2026-03-25 23:30:02', 1);
